"use client";

import Image from "next/image";
import { useEffect, useState } from "react";
import type { Product } from "@/types/rong-dhonu";

interface SwiperCarouselProps {
  slides: Product[];
  className?: string;
  componentSize?: "sm" | "md" | "lg";
}

export default function SwiperCarousel({ slides, className = "", componentSize = "md" }: SwiperCarouselProps) {
  const [index, setIndex] = useState(0);
  useEffect(() => {
    if (slides.length < 2) return;
    const timer = window.setInterval(() => setIndex((current) => (current + 1) % slides.length), 3200);
    return () => window.clearInterval(timer);
  }, [slides.length]);
  if (!slides.length) return null;
  const product = slides[index];
  return (
    <div className={`relative overflow-hidden rounded-sm border border-neutral-800 bg-neutral-950 ${className}`}>
      <div className="absolute left-0 top-0 z-10 h-1 w-full bg-gradient-to-r from-red-600 via-amber-500 to-green-500" />
      <div className="relative aspect-square">
        <Image src={product.image} alt={product.name} fill sizes="(max-width: 768px) 90vw, 520px" className="object-contain p-5 sm:p-8" priority={index === 0} />
        <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black via-black/70 to-transparent p-4 pt-20 sm:p-6 sm:pt-28">
          <div className="mb-1 text-[9px] font-black uppercase tracking-[0.25em] text-amber-500 sm:text-[10px]">{product.category}</div>
          <h3 className="text-lg font-black text-white sm:text-2xl">{product.name}</h3>
          <p className="mt-1 max-w-md text-[10px] leading-relaxed text-neutral-400 sm:text-xs">{product.desc}</p>
        </div>
      </div>
      <div className="absolute bottom-3 right-3 z-20 flex gap-1.5 sm:bottom-4 sm:right-4">
        {slides.map((slide, dotIndex) => (
          <button key={slide.id} type="button" aria-label={`Show ${slide.name}`} onClick={() => setIndex(dotIndex)} className={`h-1.5 rounded-full transition-all ${dotIndex === index ? "w-7 bg-amber-500" : "w-1.5 bg-white/30 hover:bg-white/60"}`} />
        ))}
      </div>
    </div>
  );
}
