import { BRAND } from "@/data/brand";

export default function ContactSection() {
  return <section id="contact" className="bg-black py-12 sm:py-24"><div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8"><div className="mb-8 text-center sm:mb-16"><div className="mb-3 flex items-center justify-center gap-2 sm:mb-4 sm:gap-3"><div className="h-px w-6 bg-red-600 sm:w-12" /><span className="text-[10px] font-black uppercase tracking-[0.2em] text-red-600 sm:text-xs sm:tracking-[0.4em]">Contact Information</span><div className="h-px w-6 bg-red-600 sm:w-12" /></div><h2 className="text-2xl font-black text-white sm:text-5xl">MIRPUR, DHAKA &amp; <span className="text-red-600">BANGLADESH</span></h2></div><div className="grid gap-4 sm:gap-8 lg:grid-cols-2"><ContactCard icon="📍" title="Office" rows={[["Address", "Mirpur Shopping Complex, Lift No. 9"], ["Location", "Mirpur-2, Dhaka, Bangladesh"], ["Phone", BRAND.phone]]} /><ContactCard icon="🌐" title="Online" rows={[["Email", BRAND.email], ["Website", BRAND.website], ["Tagline", BRAND.tagline]]} /></div></div></section>;
}

function ContactCard({ icon, title, rows }: { icon: string; title: string; rows: string[][] }) {
  return <div className="rounded-sm border border-neutral-800 bg-neutral-900 p-4 sm:p-8"><div className="mb-3 flex items-center gap-2 sm:mb-6 sm:gap-3"><span className="text-2xl sm:text-3xl">{icon}</span><h3 className="text-base font-black text-white sm:text-xl">{title}</h3></div><div className="space-y-2 text-[10px] sm:space-y-3 sm:text-sm">{rows.map(([key, value]) => <div key={key} className="flex gap-2 sm:gap-4"><span className="w-16 shrink-0 text-[9px] text-neutral-600 sm:w-24 sm:text-xs">{key}</span><span className="text-[9px] text-neutral-300 sm:text-xs">{value}</span></div>)}</div></div>;
}
