import type { Tier } from "@/types/rong-dhonu";

export default function TierBadge({ tier }: { tier: Tier }) {
  return tier === "exclusive" ? (
    <span className="px-1.5 py-0.5 text-[8px] sm:px-2 sm:py-0.5 sm:text-[10px] font-black tracking-widest bg-amber-500 text-black rounded-sm uppercase">EXCLUSIVE</span>
  ) : (
    <span className="px-1.5 py-0.5 text-[8px] sm:px-2 sm:py-0.5 sm:text-[10px] font-black tracking-widest border border-neutral-600 text-neutral-400 rounded-sm uppercase">COMMUNITY</span>
  );
}
