"use client";

import Image from "next/image";
import { useState } from "react";
import type { Product } from "@/types/rong-dhonu";
import TierBadge from "./TierBadge";

export default function ProductCard({ product }: { product: Product }) {
  const [added, setAdded] = useState(false);
  const handleAdd = () => { setAdded(true); window.setTimeout(() => setAdded(false), 2000); };
  return (
    <article className="group relative flex flex-col overflow-hidden rounded-sm border border-neutral-800 bg-neutral-900 transition-all duration-300 hover:border-neutral-600">
      <div className={`h-0.5 ${product.tier === "exclusive" ? "bg-amber-500" : "bg-neutral-700"}`} />
      <div className="relative bg-neutral-950 text-center"><Image src={product.image} alt={product.name} width={600} height={600} className="h-64 w-full object-contain sm:h-72" />{product.badge && <div className="absolute left-2 top-2 rounded-sm bg-red-600 px-1 py-0.5 text-[8px] font-black uppercase tracking-widest text-white sm:left-3 sm:top-3 sm:px-2">{product.badge}</div>}<div className="absolute right-2 top-2 sm:right-3 sm:top-3"><TierBadge tier={product.tier} /></div></div>
      <div className="flex flex-1 flex-col p-3 sm:p-5"><div className="mb-1 text-[10px] font-bold uppercase tracking-widest text-neutral-500 sm:text-xs">{product.category}</div><h3 className="mb-1 text-sm font-black leading-tight text-white sm:mb-2 sm:text-base">{product.name}</h3><p className="mb-3 flex-1 text-[10px] leading-relaxed text-neutral-500 sm:mb-4 sm:text-xs">{product.desc}</p><div className="mb-3 flex items-baseline gap-2"><span className="text-lg font-black text-white sm:text-xl">{product.price}</span><span className="text-[9px] text-neutral-600 sm:text-xs">{product.priceBDT}</span></div><button onClick={handleAdd} className={`w-full rounded-sm py-2 text-[10px] font-black uppercase tracking-widest transition-all sm:py-3 sm:text-xs ${added ? "bg-green-600 text-white" : product.tier === "exclusive" ? "bg-amber-500 text-black hover:bg-amber-400" : "border border-neutral-700 bg-neutral-800 text-white hover:bg-neutral-700"}`}>{added ? "✓ Added" : product.tier === "exclusive" ? "View Details" : "View Asset"}</button></div>
    </article>
  );
}
