import type { Platform } from "@/types/rong-dhonu";

const ICONS: Record<Platform, string> = {
  instagram: "📸",
  tiktok: "🎵",
  youtube: "▶️",
  facebook: "📘",
};

export default function PlatformIcon({ platform }: { platform: Platform }) {
  return <span aria-hidden="true">{ICONS[platform] ?? "📱"}</span>;
}
