"use client";

import { useState } from "react";
import BrandLogo from "./BrandLogo";

export default function NewsletterSection() {
  const [email, setEmail] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const handleSubmit = (event: React.FormEvent) => { event.preventDefault(); if (email.trim()) setSubmitted(true); };
  return <section className="bg-neutral-950 p-4 py-12 sm:py-20"><div className="mx-auto max-w-3xl text-center"><div className="flex justify-center"><BrandLogo size={72} showTagline /></div><h2 className="mb-2 mt-6 text-2xl font-black text-white sm:mb-4 sm:text-4xl">CONTACT <span className="text-amber-500">US</span></h2><p className="mb-6 text-sm text-neutral-400 sm:mb-10 sm:text-base">Use the contact details below for corporate enquiries and renovation services.</p>{submitted ? <div className="rounded-sm border border-green-600/40 bg-green-950/30 p-3 text-sm font-black text-green-400 sm:p-6 sm:text-lg">✓ Thank you. We'll be in touch.</div> : <form onSubmit={handleSubmit} className="mx-auto flex max-w-lg flex-col gap-2 sm:flex-row sm:gap-3"><input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="your@email.com" className="flex-1 rounded-sm border border-neutral-700 bg-neutral-900 px-3 py-2.5 text-xs text-white placeholder-neutral-600 focus:border-amber-500 focus:outline-none sm:px-4 sm:py-4 sm:text-sm" required /><button type="submit" className="rounded-sm bg-amber-500 px-4 py-2.5 text-[10px] font-black uppercase tracking-widest text-black transition-colors hover:bg-amber-400 sm:px-6 sm:py-4 sm:text-xs">Send Enquiry</button></form>}</div></section>;
}
