import Image from "next/image";
import { BRAND } from "@/data/brand";

interface BrandLogoProps {
  size?: number;
  showTagline?: boolean;
  className?: string;
}

export default function BrandLogo({ size = 80, showTagline = false, className = "" }: BrandLogoProps) {
  return (
    <div className={`flex items-center gap-3 ${className}`}>
      <Image src={BRAND.assets.logo} alt={BRAND.name} width={size} height={size} className="object-contain" />
      {showTagline && <span className="text-amber-500 text-[10px] tracking-[0.25em] uppercase font-bold">{BRAND.tagline}</span>}
    </div>
  );
}
