import { BRAND } from "@/data/brand";

const corporate = ["Rong Dhonu Renovation Limited wordmark", "Rainbow renovation emblem", "COLOR | DESIGN | TRANSFORM tagline", "Navy and multicolor visual accents"];
const collateral = ["Business card and letterhead", "CV / document folder", "Branded corporate T-shirt", "Consistent logo and color treatment"];

function SegmentCard({ id, title, subtitle, icon, items, accent, footerLabel, footerValue }: { id: string; title: string; subtitle: string; icon: string; items: string[]; accent: "amber" | "red"; footerLabel: string; footerValue: string }) {
  const border = accent === "amber" ? "border-amber-500/40 hover:border-amber-500" : "border-red-600/30 hover:border-red-600/60";
  const text = accent === "amber" ? "text-amber-500" : "text-red-500";
  return <div id={id} className={`relative rounded-sm border bg-linear-to-br from-neutral-900 to-black p-4 transition-all duration-300 sm:p-8 ${border}`}><div className={`absolute left-0 top-0 h-0.5 w-full bg-linear-to-r ${accent === "amber" ? "from-amber-500" : "from-red-600"} to-transparent`} /><div className="mb-3 flex items-center gap-2 sm:mb-6 sm:gap-4"><span className="text-2xl sm:text-4xl">{icon}</span><div><h3 className={`${text} text-lg font-black tracking-tight sm:text-2xl`}>{title}</h3><p className="text-[10px] text-neutral-500 sm:text-sm">{subtitle}</p></div></div><div className="mb-4 space-y-2 sm:mb-8 sm:space-y-3">{items.map((item) => <div key={item} className="flex items-center gap-2 text-xs sm:gap-3 sm:text-sm"><span className={`${text} font-black`}>{accent === "amber" ? "✦" : "▸"}</span><span className="text-neutral-300">{item}</span></div>)}</div><div className="rounded-sm border border-neutral-800 bg-black/50 p-2 sm:p-4"><div className="text-[8px] uppercase tracking-wider text-neutral-500 sm:text-xs">{footerLabel}</div><div className="text-sm font-black text-white sm:text-lg">{footerValue}</div></div></div>;
}

export default function SegmentsSection() {
  return <section className="bg-neutral-950 py-12 sm:py-24"><div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8"><div className="mb-8 text-center sm:mb-16"><div className="mb-3 flex items-center justify-center gap-2 sm:mb-4 sm:gap-3"><div className="h-px w-6 bg-amber-500 sm:w-12" /><span className="text-[10px] font-black uppercase tracking-[0.2em] text-amber-500 sm:text-xs sm:tracking-[0.4em]">Brand Identity</span><div className="h-px w-6 bg-amber-500 sm:w-12" /></div><h2 className="text-2xl font-black text-white sm:text-5xl">OUR <span className="text-amber-500">BRAND SYSTEM</span></h2></div><div className="grid gap-4 sm:gap-8 lg:grid-cols-2"><SegmentCard id="corporate" title="CORPORATE IDENTITY" subtitle="Official brand elements" icon="🎨" items={corporate} accent="amber" footerLabel="Tagline" footerValue={BRAND.tagline} /><SegmentCard id="public" title="CORPORATE COLLATERAL" subtitle="Consistent presentation across materials" icon="📁" items={collateral} accent="red" footerLabel="Primary location" footerValue="Mirpur-2, Dhaka, Bangladesh" /></div></div></section>;
}
