interface MobileMenuProps {
  isOpen: boolean;
  onClose: () => void;
}

export default function MobileMenu({ isOpen, onClose }: MobileMenuProps) {
  if (!isOpen) return null;
  return (
    <>
      <div className="fixed inset-0 z-40 bg-black/80" onClick={onClose} />
      <aside className="fixed top-0 right-0 z-50 h-full w-64 bg-neutral-900 p-6 shadow-xl">
        <button onClick={onClose} className="absolute right-4 top-4 text-2xl text-white" aria-label="Close menu">&times;</button>
        <div className="mt-8 flex flex-col gap-4">
          {["Collection", "Corporate", "Public", "About", "Contact"].map((link) => (
            <a key={link} href={`#${link.toLowerCase()}`} onClick={onClose} className="text-sm font-bold uppercase tracking-wider text-neutral-400 transition-colors hover:text-amber-500">{link}</a>
          ))}
          <a href="#collection" onClick={onClose} className="mt-2 rounded-lg bg-red-600 px-4 py-2 text-center text-xs font-black uppercase tracking-widest text-white transition-colors hover:bg-red-500">View Brand</a>
        </div>
      </aside>
    </>
  );
}
